import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 4

def design(feats):
    # Identify highly correlated pairs
    corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.append((feats.ids[i], feats.ids[j]))

    # Cluster correlated features
    if not corr_pairs:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build adjacency matrix
    feat_to_idx = {fid: i for i, fid in enumerate(feats.ids)}
    n_feats = len(feats.ids)
    adj = np.zeros((n_feats, n_feats))

    for a, b in corr_pairs:
        i, j = feat_to_idx[a], feat_to_idx[b]
        adj[i,j] = adj[j,i] = 1

    # Use clustering to find modules
    clustering = AgglomerativeClustering(n_clusters=2, linkage='single')
    labels = clustering.fit_predict(1-adj)

    # Find largest cluster
    unique_labels, counts = np.unique(labels, return_counts=True)
    main_cluster = unique_labels[np.argmax(counts)]
    module_ids = [feats.ids[i] for i in range(n_feats) if labels[i] == main_cluster]

    # If module size is small, no mechanism
    if len(module_ids) < 3:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute weighted score using t-statistics as weights
    loadings = {}
    for fid in module_ids:
        idx = feats.column(fid)
        t_stat = stats.ttest_ind(feats.x[feats.y==1, idx], feats.x[feats.y==0, idx]).statistic
        loadings[fid] = t_stat

    # Normalize loadings
    total_weight = sum(abs(w) for w in loadings.values())
    if total_weight > 0:
        loadings = {k: v/total_weight for k, v in loadings.items()}

    # Select top features for regression
    columns = tuple(sorted(loadings.keys(), key=lambda x: abs(loadings[x]), reverse=True)[:10])

    # Create products between top features
    products = []
    for i, a in enumerate(columns[:5]):
        for b in columns[i+1:i+3]:
            products.append((a,b))

    # Drivers are the top features by effect size
    drivers = tuple(sorted(loadings.keys(), key=lambda x: abs(loadings[x]), reverse=True)[:MAX_DRIVERS])

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
